import * as React from "react";
import { ArrowDownIcon, ArrowUpIcon, ArrowUpDownIcon, ChevronLeftIcon, ChevronRightIcon } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "./button";
import { IconButton } from "./icon-button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "./table";

/**
 * figma: Data Table — the page composes Table, Checkbox and DropdownMenu
 * rather than defining a component set of its own.
 *
 * Sorting, selection and pagination are plain React state on top of this
 * library's own Table. There is deliberately no table library underneath: the
 * shadcn CLI always installs `latest` for a component's dependencies, so a
 * major release upstream would silently break every new install. For anything
 * heavier — grouping, virtualisation, server-side paging — drop TanStack Table
 * in yourself and render through these same parts.
 */
export type DataTableColumn<T> = {
  /** Key into the row, or a unique id when using `cell`. */
  id: string;
  header: React.ReactNode;
  /** Defaults to `row[id]`. */
  cell?: (row: T) => React.ReactNode;
  /** Enables the sort control on this column. */
  sortable?: boolean;
  /** Value used for sorting; defaults to `row[id]`. */
  sortValue?: (row: T) => string | number;
  className?: string;
};

type SortState = { id: string; desc: boolean } | null;

function DataTable<T extends Record<string, unknown>>({
  columns,
  data,
  className,
  pageSize = 10,
  emptyMessage = "No results.",
  getRowId,
  selectable = false,
  onSelectionChange,
  children,
}: {
  columns: DataTableColumn<T>[];
  data: T[];
  className?: string;
  pageSize?: number;
  emptyMessage?: React.ReactNode;
  getRowId?: (row: T, index: number) => string;
  selectable?: boolean;
  onSelectionChange?: (rows: T[]) => void;
  /** Toolbar above the table — filters, column toggles. */
  children?: React.ReactNode;
}) {
  const [sort, setSort] = React.useState<SortState>(null);
  const [page, setPage] = React.useState(0);
  const [selected, setSelected] = React.useState<Set<string>>(new Set());

  const rowId = React.useCallback(
    (row: T, i: number) => (getRowId ? getRowId(row, i) : String(i)),
    [getRowId]
  );

  const sorted = React.useMemo(() => {
    if (!sort) return data;
    const column = columns.find((c) => c.id === sort.id);
    const value = (row: T) =>
      column?.sortValue ? column.sortValue(row) : (row[sort.id] as string | number);
    return [...data].sort((a, b) => {
      const av = value(a);
      const bv = value(b);
      if (av === bv) return 0;
      return (av > bv ? 1 : -1) * (sort.desc ? -1 : 1);
    });
  }, [data, sort, columns]);

  const pageCount = Math.max(1, Math.ceil(sorted.length / pageSize));
  const current = Math.min(page, pageCount - 1);
  const rows = sorted.slice(current * pageSize, current * pageSize + pageSize);

  const toggle = (id: string) => {
    const next = new Set(selected);
    next.has(id) ? next.delete(id) : next.add(id);
    setSelected(next);
    onSelectionChange?.(data.filter((row, i) => next.has(rowId(row, i))));
  };

  const toggleSort = (id: string) =>
    setSort((s) => (s?.id === id ? (s.desc ? null : { id, desc: true }) : { id, desc: false }));

  return (
    <div data-slot="data-table" className={cn("flex flex-col gap-4", className)}>
      {children}
      <div className="rounded-xl border">
        <Table>
          <TableHeader>
            <TableRow>
              {selectable ? <TableHead className="w-10" /> : null}
              {columns.map((column) => (
                <TableHead key={column.id} className={column.className}>
                  {column.sortable ? (
                    <Button variant="ghost" size="xs" className="-ms-2" onClick={() => toggleSort(column.id)}>
                      {column.header}
                      {sort?.id !== column.id ? (
                        <ArrowUpDownIcon data-icon="inline-end" />
                      ) : sort.desc ? (
                        <ArrowDownIcon data-icon="inline-end" />
                      ) : (
                        <ArrowUpIcon data-icon="inline-end" />
                      )}
                    </Button>
                  ) : (
                    column.header
                  )}
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.length ? (
              rows.map((row, i) => {
                const id = rowId(row, current * pageSize + i);
                return (
                  <TableRow key={id} data-state={selected.has(id) ? "selected" : undefined}>
                    {selectable ? (
                      <TableCell>
                        <input
                          type="checkbox"
                          aria-label="Select row"
                          checked={selected.has(id)}
                          onChange={() => toggle(id)}
                        />
                      </TableCell>
                    ) : null}
                    {columns.map((column) => (
                      <TableCell key={column.id} className={column.className}>
                        {column.cell ? column.cell(row) : String(row[column.id] ?? "")}
                      </TableCell>
                    ))}
                  </TableRow>
                );
              })
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length + (selectable ? 1 : 0)}
                  className="h-24 text-center text-muted-foreground"
                >
                  {emptyMessage}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination
        page={current}
        pageCount={pageCount}
        selectedCount={selected.size}
        total={sorted.length}
        onPrevious={() => setPage((p) => Math.max(0, p - 1))}
        onNext={() => setPage((p) => Math.min(pageCount - 1, p + 1))}
      />
    </div>
  );
}

function DataTablePagination({
  page,
  pageCount,
  selectedCount,
  total,
  onPrevious,
  onNext,
}: {
  page: number;
  pageCount: number;
  selectedCount: number;
  total: number;
  onPrevious: () => void;
  onNext: () => void;
}) {
  return (
    <div data-slot="data-table-pagination" className="flex items-center justify-between gap-2">
      <div className="text-sm text-muted-foreground">
        {selectedCount} of {total} row(s) selected.
      </div>
      <div className="flex items-center gap-2">
        <span className="text-sm text-muted-foreground">
          Page {page + 1} of {pageCount}
        </span>
        <IconButton variant="outline" size="sm" aria-label="Previous page" disabled={page === 0} onClick={onPrevious}>
          <ChevronLeftIcon className="rtl:rotate-180" />
        </IconButton>
        <IconButton
          variant="outline"
          size="sm"
          aria-label="Next page"
          disabled={page >= pageCount - 1}
          onClick={onNext}
        >
          <ChevronRightIcon className="rtl:rotate-180" />
        </IconButton>
      </div>
    </div>
  );
}

export { DataTable, DataTablePagination };
